SELECT COUNT(*) AS closed_events, COALESCE(SUM(time_min), 0) AS total_downtime_min, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(time_min), 0) / COUNT(*), 2) END AS mttr_min, CASE WHEN COUNT(*) <= 1 THEN 480 ELSE ROUND(480.0 * (SELECT COUNT(DISTINCT equipment_id) FROM emc_work_calendar) / COUNT(*), 2) END AS mtbf_min FROM emc_operations_event WHERE status = 'CLOSED' AND COALESCE(time_min, 0) > 0
